// @FIGURE_CODE_BEGIN
var FIG_W = 640, FIG_H = 560;
var figDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
figDraw.viewbox(0, 0, FIG_W, FIG_H);

var RED = '#ee1c25', BLUE = '#1f6fd0', GRN = '#0f9d58', GREENBG = '#dbeee1', INK = '#111';

var figStatic = figDraw.group();
var figCurveL = figDraw.group();
var figDynL = figDraw.group();

var figState = {
  mode: 'a',
  t: 0,
  comp: false,
  curves: {
    a: { p0: [-Math.PI / 2, 2], p1: [-Math.PI / 2, 1] },
    b: { xs: -1, xe: 2 }
  }
};
var figPanels = {};

/* ---------- small helpers ---------- */
function figClamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function fmt(v) { return (Math.abs(v) < 5e-4 ? 0 : v).toFixed(3); }

function figLabel(g, str, x, y, size, o) {
  o = o || {};
  var t = g.text(str);
  t.font({
    family: o.family || 'Georgia, "Times New Roman", serif',
    size: size,
    anchor: o.anchor || 'middle',
    style: o.italic ? 'italic' : 'normal',
    weight: o.weight || 'normal'
  });
  t.fill(o.fill || INK);
  t.attr({ x: x, y: y, 'dominant-baseline': 'central' });
  var tsp = t.node.querySelector('tspan');
  if (tsp) { tsp.setAttribute('x', x); tsp.setAttribute('dy', 0); }
  if (o.halo !== false) {
    t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': o.halo || 3, 'stroke-linejoin': 'round' });
  }
  return t;
}

function figArrow(g, x1, y1, x2, y2, color, w, head, op) {
  var dx = x2 - x1, dy = y2 - y1, len = Math.hypot(dx, dy);
  if (len < 1e-6) return null;
  var ux = dx / len, uy = dy / len;
  var bx = x2 - ux * head, by = y2 - uy * head;
  var gg = g.group();
  gg.line(x1, y1, bx, by).stroke({ color: color, width: w, linecap: 'round' });
  var px = -uy, py = ux, hw = head * 0.44;
  gg.polygon([[x2, y2], [bx + px * hw, by + py * hw], [bx - px * hw, by - py * hw]]).fill(color);
  if (op != null) gg.opacity(op);
  return gg;
}

/* ---------- curve math ---------- */
function curvePoint(key, t) {
  if (key === 'a') {
    var c = figState.curves.a;
    return [c.p0[0] + t * (c.p1[0] - c.p0[0]), c.p0[1] + t * (c.p1[1] - c.p0[1])];
  }
  var b = figState.curves.b, x = b.xs + t * (b.xe - b.xs);
  return [x, x * x];
}
function curveDeriv(key, t) {
  if (key === 'a') {
    var c = figState.curves.a;
    return [c.p1[0] - c.p0[0], c.p1[1] - c.p0[1]];
  }
  var b = figState.curves.b, dx = b.xe - b.xs, x = b.xs + t * dx;
  return [dx, 2 * x * dx];
}
function fieldAt(p) { return [Math.cos(p[0]), Math.sin(p[0])]; }
function gVal(key, t) {
  var p = curvePoint(key, t), d = curveDeriv(key, t), F = fieldAt(p);
  return F[0] * d[0] + F[1] * d[1];
}
var CUMN = 240;
function cumTable(key) {
  var arr = new Array(CUMN + 1), dt = 1 / CUMN, acc = 0;
  arr[0] = 0;
  for (var i = 1; i <= CUMN; i++) { acc += gVal(key, (i - 0.5) * dt) * dt; arr[i] = acc; }
  return arr;
}
function runningAt(tbl, t) {
  var x = figClamp(t, 0, 1) * CUMN, i = Math.floor(x);
  if (i >= CUMN) return tbl[CUMN];
  return tbl[i] + (tbl[i + 1] - tbl[i]) * (x - i);
}

/* ---------- panels ---------- */
function mkPanel(key, x, y, w, h) {
  var base = (key === 'a')
    ? { xd: [-2.95, 1.55], yd: [-1.15, 2.95], nx: 10, ny: 12 }
    : { xd: [-2.45, 3.35], yd: [-0.80, 4.80], nx: 12, ny: 12 };
  var xr = base.xd[1] - base.xd[0], yr = base.yd[1] - base.yd[0];
  var s = Math.min(w / xr, h / yr);
  var nxr = w / s, nyr = h / s;
  var cx = (base.xd[0] + base.xd[1]) / 2, cy = (base.yd[0] + base.yd[1]) / 2;
  var P = {
    key: key, x: x, y: y, w: w, h: h, s: s, nx: base.nx, ny: base.ny,
    xd: [cx - nxr / 2, cx + nxr / 2],
    yd: [cy - nyr / 2, cy + nyr / 2]
  };
  P.X = function (wx) { return P.x + (wx - P.xd[0]) * P.s; };
  P.Y = function (wy) { return P.y + P.h - (wy - P.yd[0]) * P.s; };
  P.invX = function (px) { return P.xd[0] + (px - P.x) / P.s; };
  P.invY = function (py) { return P.yd[0] + (P.y + P.h - py) / P.s; };
  return P;
}

function figLayout() {
  figPanels = {};
  if (figState.mode === 'both') {
    figPanels.a = mkPanel('a', 36, 76, 234, 230);
    figPanels.b = mkPanel('b', 322, 76, 234, 230);
  } else if (figState.mode === 'a') {
    figPanels.a = mkPanel('a', 52, 80, 296, 290);
  } else {
    figPanels.b = mkPanel('b', 52, 80, 296, 290);
  }
}

/* ---------- static drawing ---------- */
function drawPanelStatic(P) {
  var g = figStatic.group();
  var bg = g.rect(P.w, P.h).move(P.x, P.y).fill(GREENBG);
  bg.css('cursor', 'help');
  bg.on('mousemove', function (e) {
    showTooltip('F = cos(x) i + sin(x) j — all arrows drawn the same length, so only direction is meaningful. Direction depends only on x.', e);
  }).on('mouseleave', hideTooltip).on('click', function () {
    showPopup('The field F = cos(x) i + sin(x) j',
      'Both components depend only on x, so the field is constant along every vertical line. Near x = -\u03C0/2 the arrows point straight down, near x = 0 they point straight right, and for x > 0 they tilt up and to the right. Lengths are normalised for readability — "vectors not to scale".');
  });

  // field lattice
  var dxw = (P.xd[1] - P.xd[0]) / P.nx, dyw = (P.yd[1] - P.yd[0]) / P.ny;
  var L = Math.min(P.w / P.nx, P.h / P.ny) * 0.84;
  var fg = g.group();
  for (var i = 0; i < P.nx; i++) {
    for (var j = 0; j < P.ny; j++) {
      var wx = P.xd[0] + (i + 0.5) * dxw, wy = P.yd[0] + (j + 0.5) * dyw;
      var ux = Math.cos(wx), uy = Math.sin(wx);
      var cx = P.X(wx), cy = P.Y(wy);
      figArrow(fg, cx - ux * L / 2, cy + uy * L / 2, cx + ux * L / 2, cy - uy * L / 2,
        INK, Math.max(0.7, L * 0.075), L * 0.38, 1);
    }
  }

  // axes
  var y0 = P.Y(0), x0 = P.X(0);
  var ag = g.group();
  figArrow(ag, P.x - 14, y0, P.x + P.w + 24, y0, INK, 1.9, 11, 1);
  figArrow(ag, x0, P.y + P.h + 14, x0, P.y - 24, INK, 1.9, 11, 1);
  figLabel(ag, 'x', P.x + P.w + 32, y0 - 14, 16, { italic: true });
  figLabel(ag, 'y', x0 + 14, P.y - 28, 16, { italic: true });

  // ticks
  var tg = g.group(), k, v;
  if (P.key === 'a') {
    for (k = 1; k <= 2; k++) {
      tg.line(x0 - 5, P.Y(k), x0 + 5, P.Y(k)).stroke({ color: INK, width: 1.6 });
      figLabel(tg, String(k), x0 - 14, P.Y(k), 15, { anchor: 'end', italic: true });
    }
    var xp = P.X(-Math.PI / 2);
    tg.line(xp, y0 - 5, xp, y0 + 5).stroke({ color: INK, width: 1.6 });
    figLabel(tg, '\u2212', xp - 16, y0 + 22, 15, { anchor: 'middle' });
    figLabel(tg, '\u03C0', xp + 1, y0 + 13, 14, { italic: true });
    tg.line(xp - 8, y0 + 22, xp + 10, y0 + 22).stroke({ color: INK, width: 1.4 });
    figLabel(tg, '2', xp + 1, y0 + 31, 14, { italic: true });
  } else {
    var xs = [-2, -1, 1, 2, 3];
    for (k = 0; k < xs.length; k++) {
      v = xs[k];
      tg.line(P.X(v), y0 - 5, P.X(v), y0 + 5).stroke({ color: INK, width: 1.6 });
      figLabel(tg, (v < 0 ? '\u2212' : '') + Math.abs(v), P.X(v), y0 + 17, 14, { italic: true });
    }
    for (k = 1; k <= 4; k++) {
      tg.line(x0 - 5, P.Y(k), x0 + 5, P.Y(k)).stroke({ color: INK, width: 1.6 });
      figLabel(tg, String(k), x0 - 13, P.Y(k), 14, { anchor: 'end', italic: true });
    }
  }

  // caption
  figLabel(g, P.key === 'a' ? '(a)' : '(b)', P.x + P.w / 2, P.y + P.h + (figState.mode === 'both' ? 30 : 34),
    figState.mode === 'both' ? 16 : 19, { italic: true });
}

function figBuildStatic() {
  figStatic.clear();
  var keys = Object.keys(figPanels);
  for (var i = 0; i < keys.length; i++) drawPanelStatic(figPanels[keys[i]]);
  var titleP = figPanels.a || figPanels.b;
  figLabel(figStatic, 'Vectors not to scale', titleP.x + titleP.w / 2, 30, 19, { italic: true, fill: '#111' });
}

/* ---------- curve layer ---------- */
function figBuildCurves() {
  figCurveL.clear();
  var keys = Object.keys(figPanels);
  for (var i = 0; i < keys.length; i++) drawCurve(figPanels[keys[i]]);
  figBuildDynamic();
}

function drawCurve(P) {
  var g = figCurveL.group(), key = P.key, i, t, p;
  var pts = [];
  for (i = 0; i <= 90; i++) { t = i / 90; p = curvePoint(key, t); pts.push([P.X(p[0]), P.Y(p[1])]); }
  var wid = (figState.mode === 'both') ? 3.6 : 4.4;
  var poly = g.polyline(pts).fill('none').stroke({ color: RED, width: wid, linecap: 'round', linejoin: 'round' });
  var total = runningAt(cumTable(key), 1);
  poly.css('cursor', 'pointer');
  poly.on('mousemove', function (e) {
    showTooltip('Oriented curve C — \u222B_C F\u00B7dr = ' + fmt(total), e);
  }).on('mouseleave', hideTooltip).on('click', function () {
    showPopup('The oriented curve C',
      key === 'a'
        ? 'This short segment runs straight down the line x = -\u03C0/2, where the field also points straight down. Travel direction and field agree everywhere, so every contribution F\u00B7T ds is positive and the integral is ' + fmt(total) + '.'
        : 'This parabola y = x\u00B2 runs from (' + fmt(figState.curves.b.xs) + ', ' + fmt(figState.curves.b.xs * figState.curves.b.xs) + ') down through the origin and up to the right. The tangent swings around while the field rotates with x, so F\u00B7T changes sign; the total is ' + fmt(total) + '.');
  });

  // translucent orientation arrowheads
  var heads = (key === 'a') ? [0.5] : [0.22, 0.72];
  var hs = (figState.mode === 'both') ? 15 : 19;
  for (i = 0; i < heads.length; i++) {
    t = heads[i];
    p = curvePoint(key, t);
    var d = curveDeriv(key, t);
    var sx = d[0], sy = -d[1], ln = Math.hypot(sx, sy);
    if (ln < 1e-9) continue;
    var ux = sx / ln, uy = sy / ln, px = -uy, py = ux;
    var cx = P.X(p[0]), cy = P.Y(p[1]);
    g.polygon([
      [cx + ux * hs * 0.62, cy + uy * hs * 0.62],
      [cx - ux * hs * 0.38 + px * hs * 0.48, cy - uy * hs * 0.38 + py * hs * 0.48],
      [cx - ux * hs * 0.38 - px * hs * 0.48, cy - uy * hs * 0.38 - py * hs * 0.48]
    ]).fill({ color: RED, opacity: 0.5 });
  }

  // endpoints (draggable)
  [0, 1].forEach(function (which) {
    var q = curvePoint(key, which);
    var dot = g.circle((figState.mode === 'both' ? 9 : 11)).center(P.X(q[0]), P.Y(q[1])).fill(RED);
    dot.css('cursor', 'grab');
    dot.on('mousedown', function (e) { e.preventDefault(); figDrag = { key: key, which: which }; });
    dot.on('mousemove', function (e) {
      showTooltip((which === 0 ? 'Start' : 'End') + ' of C at (' + fmt(q[0]) + ', ' + fmt(q[1]) + ') — drag to reshape the path', e);
    }).on('mouseleave', hideTooltip);
  });

  // label C
  var lt = (key === 'a') ? 0.52 : 0.88;
  var lp = curvePoint(key, lt);
  var off = (key === 'a') ? [16, 16] : [20, 6];
  figLabel(g, 'C', P.X(lp[0]) + off[0], P.Y(lp[1]) + off[1], (figState.mode === 'both' ? 16 : 19), { italic: true });
}

/* ---------- dynamic layer ---------- */
function figBuildDynamic() {
  figDynL.clear();
  var keys = (figState.mode === 'both') ? ['a', 'b'] : [figState.mode];
  var i;
  for (i = 0; i < keys.length; i++) drawMarker(figPanels[keys[i]]);
  if (!figState.comp) return;
  if (figState.mode === 'both') {
    drawReadoutBoth({ x: 36, y: 352, w: 520, h: 88 }, keys);
    drawInset({ x: 36, y: 450, w: 250, h: 100 }, 'a');
    drawInset({ x: 306, y: 450, w: 250, h: 100 }, 'b');
  } else {
    drawReadoutSingle({ x: 372, y: 84, w: 246, h: 184 }, keys[0]);
    drawInset({ x: 372, y: 288, w: 246, h: 150 }, keys[0]);
  }
}

function drawMarker(P) {
  var key = P.key, t = figState.t;
  var p = curvePoint(key, t), d = curveDeriv(key, t), F = fieldAt(p);
  var cx = P.X(p[0]), cy = P.Y(p[1]);
  var g = figDynL.group();
  if (!figState.comp) {
    g.circle(11).center(cx, cy).fill('#fff').stroke({ color: RED, width: 2.6 });
    return;
  }
  var dl = Math.hypot(d[0], d[1]);
  if (dl < 1e-9) { g.circle(11).center(cx, cy).fill('#fff').stroke({ color: RED, width: 2.6 }); return; }
  var T = [d[0] / dl, d[1] / dl];
  var dot = F[0] * T[0] + F[1] * T[1];
  var k = Math.min(P.w, P.h) * 0.20;

  var Fx = cx + F[0] * k, Fy = cy - F[1] * k;
  var Tx = cx + T[0] * k, Ty = cy - T[1] * k;
  var Qx = cx + T[0] * dot * k, Qy = cy - T[1] * dot * k;

  // projection band + dashed drop line
  g.line(cx, cy, Qx, Qy).stroke({ color: BLUE, width: 9, linecap: 'butt', opacity: 0.30 });
  g.line(Fx, Fy, Qx, Qy).stroke({ color: '#666', width: 1.3, dasharray: '4,3' });

  var av = figArrow(g, cx, cy, Tx, Ty, GRN, 2.6, 10, 1);
  var af = figArrow(g, cx, cy, Fx, Fy, BLUE, 2.6, 10, 1);
  if (af) {
    af.css('cursor', 'pointer');
    af.on('mousemove', function (e) { showTooltip('F = (' + fmt(F[0]) + ', ' + fmt(F[1]) + ') — the field at this point (unit length)', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () { showPopup('The field vector F', 'F = cos(x) i + sin(x) j always has length 1 here, so only its direction relative to the direction of travel matters.'); });
  }
  if (av) {
    av.css('cursor', 'pointer');
    av.on('mousemove', function (e) { showTooltip('T = (' + fmt(T[0]) + ', ' + fmt(T[1]) + ') — unit tangent, the direction of travel', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () { showPopup('The unit tangent T', 'T points along C in the chosen orientation. The integrand is F\u00B7T: the length of the shaded projection of F onto T, positive when they agree, negative when they oppose.'); });
  }
  var mk = g.circle(12).center(cx, cy).fill('#fff').stroke({ color: RED, width: 2.6 });
  mk.css('cursor', 'pointer');
  mk.on('mousemove', function (e) { showTooltip('F\u00B7T = ' + fmt(dot) + ' at t = ' + figState.t.toFixed(2), e); })
    .on('mouseleave', hideTooltip);
}

function readoutLines(key) {
  var t = figState.t, p = curvePoint(key, t), d = curveDeriv(key, t), F = fieldAt(p);
  var dl = Math.hypot(d[0], d[1]);
  var T = dl > 1e-9 ? [d[0] / dl, d[1] / dl] : [0, 0];
  var tbl = cumTable(key);
  return {
    p: p, F: F, T: T, dot: F[0] * T[0] + F[1] * T[1],
    run: runningAt(tbl, t), total: tbl[CUMN], t: t
  };
}

function drawReadoutSingle(r, key) {
  var g = figDynL.group();
  var box = g.rect(r.w, r.h).move(r.x, r.y).fill('#ffffff').stroke({ color: '#c9ced4', width: 1 }).radius(6);
  box.css('cursor', 'pointer');
  box.on('click', function () {
    showPopup('Reading the line integral',
      'At each t the point on C has a field vector F and a unit tangent T. The integrand F\u00B7T is the signed length of F projected onto T; multiplied by arc length and summed it gives \u222B_C F\u00B7dr. Positive where the path runs with the field, negative where it runs against it, zero where they are perpendicular.');
  }).on('mousemove', function (e) { showTooltip('Click for how this readout builds the integral', e); })
    .on('mouseleave', hideTooltip);

  var R = readoutLines(key);
  var mono = 'ui-monospace, Consolas, monospace';
  var x = r.x + 13, y = r.y + 20, dy = 21;
  figLabel(g, 'Curve C \u2014 panel (' + key + ')', x, y, 12.5, { anchor: 'start', weight: 'bold', halo: false, family: 'sans-serif' }); y += dy;
  figLabel(g, 't = ' + R.t.toFixed(2), x, y, 11.5, { anchor: 'start', halo: false, family: mono }); y += dy;
  figLabel(g, 'point = (' + fmt(R.p[0]) + ', ' + fmt(R.p[1]) + ')', x, y, 11.5, { anchor: 'start', halo: false, family: mono }); y += dy;
  figLabel(g, 'F = (' + fmt(R.F[0]) + ', ' + fmt(R.F[1]) + ')', x, y, 11.5, { anchor: 'start', halo: false, family: mono, fill: BLUE }); y += dy;
  figLabel(g, 'T = (' + fmt(R.T[0]) + ', ' + fmt(R.T[1]) + ')', x, y, 11.5, { anchor: 'start', halo: false, family: mono, fill: GRN }); y += dy;
  figLabel(g, 'F \u00B7 T = ' + fmt(R.dot), x, y, 11.5, { anchor: 'start', halo: false, family: mono }); y += dy;
  figLabel(g, '\u222B so far = ' + fmt(R.run), x, y, 11.5, { anchor: 'start', halo: false, family: mono }); y += dy;
  figLabel(g, 'total \u222B_C F\u00B7dr = ' + fmt(R.total), x, y, 12, { anchor: 'start', weight: 'bold', halo: false, family: mono, fill: '#8a1020' });
}

function drawReadoutBoth(r, keys) {
  var g = figDynL.group();
  g.rect(r.w, r.h).move(r.x, r.y).fill('#ffffff').stroke({ color: '#c9ced4', width: 1 }).radius(6);
  var mono = 'ui-monospace, Consolas, monospace';
  for (var i = 0; i < keys.length; i++) {
    var key = keys[i], R = readoutLines(key);
    var x = r.x + 14 + i * 268, y = r.y + 20;
    figLabel(g, 'Panel (' + key + ') ' + (key === 'a' ? '\u2014 vertical segment' : '\u2014 parabolic arc'),
      x, y, 11.5, { anchor: 'start', weight: 'bold', halo: false, family: 'sans-serif' });
    y += 21;
    figLabel(g, 'F\u00B7T = ' + fmt(R.dot) + '   \u222B so far = ' + fmt(R.run), x, y, 11, { anchor: 'start', halo: false, family: mono });
    y += 21;
    figLabel(g, 'total \u222B_C F\u00B7dr = ' + fmt(R.total), x, y, 11.5, { anchor: 'start', weight: 'bold', halo: false, family: mono, fill: '#8a1020' });
  }
}

function drawInset(r, key) {
  var g = figDynL.group();
  g.rect(r.w, r.h).move(r.x, r.y).fill('#ffffff').stroke({ color: '#c9ced4', width: 1 }).radius(6);
  figLabel(g, 'F\u00B7T ds/dt  vs  t   (shaded area = \u222B)', r.x + r.w / 2, r.y + 13, 10, { halo: false, family: 'sans-serif', fill: '#333' });

  var px = r.x + 24, py = r.y + 26, pw = r.w - 36, ph = r.h - 42;
  var N = 72, i, vals = [], mx = 1e-6;
  for (i = 0; i <= N; i++) { var v = gVal(key, i / N); vals.push(v); mx = Math.max(mx, Math.abs(v)); }
  mx *= 1.15;
  var mapT = function (t) { return px + t * pw; };
  var mapG = function (v) { return py + ph / 2 - (v / mx) * (ph / 2); };

  // shaded signed area up to current t
  var tc = figState.t;
