// @FIGURE_CODE_BEGIN
var FIG_W = 640, FIG_H = 560;
var figDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
figDraw.viewbox(0, 0, FIG_W, FIG_H);

var RED = '#ee1c25', BLUE = '#1f6fd0', GRN = '#0f9d58', GREENBG = '#dceee2', INK = '#111';
var POS = '#3b82f6', NEG = '#f2802b';

var figStatic = figDraw.group();
var figCurveL = figDraw.group();
var figDynL = figDraw.group();

var figState = {
  mode: 'a',
  t: 0,
  comp: false,
  curves: {
    a: { p0: [-Math.PI / 2, 2], p1: [-Math.PI / 2, 1] },   // starts high, travels DOWN
    b: { xs: -1, xe: 2 }
  }
};
var figPanels = {};

/* ---------- helpers ---------- */
function figClamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function fmt(v) { return (Math.abs(v) < 5e-4 ? 0 : v).toFixed(3); }

function figLabel(g, str, x, y, size, o) {
  o = o || {};
  var t = g.text(str);
  t.font({
    family: o.family || 'Georgia, "Times New Roman", serif',
    size: size,
    anchor: o.anchor || 'middle',
    style: o.italic ? 'italic' : 'normal',
    weight: o.weight || 'normal'
  });
  t.fill(o.fill || INK);
  t.attr({ x: x, y: y, 'dominant-baseline': 'central' });
  var tsp = t.node.querySelector('tspan');
  if (tsp) { tsp.setAttribute('x', x); tsp.setAttribute('dy', 0); }
  if (o.halo !== false) {
    t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': o.halo || 3, 'stroke-linejoin': 'round' });
  }
  return t;
}

function figArrow(g, x1, y1, x2, y2, color, w, head, op) {
  var dx = x2 - x1, dy = y2 - y1, len = Math.hypot(dx, dy);
  if (len < 1e-6) return null;
  var ux = dx / len, uy = dy / len;
  var bx = x2 - ux * head, by = y2 - uy * head;
  var gg = g.group();
  gg.line(x1, y1, bx, by).stroke({ color: color, width: w, linecap: 'round' });
  var px = -uy, py = ux, hw = head * 0.44;
  gg.polygon([[x2, y2], [bx + px * hw, by + py * hw], [bx - px * hw, by - py * hw]]).fill(color);
  if (op != null) gg.opacity(op);
  return gg;
}

/* stacked fraction  -pi/2  centred at xc, top edge at ytop */
function drawNegPiOver2(g, xc, ytop, fs) {
  var barY = ytop + fs * 0.95;
  var bw = fs * 0.46;
  g.rect(fs * 2.45, fs * 2.25).move(xc - fs * 1.62, ytop - fs * 0.18)
    .fill('#ffffff').opacity(0.82).radius(3);
  figLabel(g, '\u03C0', xc, barY - fs * 0.60, fs, { italic: true, halo: false });
  g.line(xc - bw, barY, xc + bw, barY).stroke({ color: INK, width: Math.max(1, fs * 0.095) });
  figLabel(g, '2', xc, barY + fs * 0.68, fs, { italic: true, halo: false });
  figLabel(g, '\u2212', xc - fs * 0.98, barY, fs * 1.05, { halo: false });
}

/* ---------- curve math ---------- */
function curvePoint(key, t) {
  if (key === 'a') {
    var c = figState.curves.a;
    return [c.p0[0] + t * (c.p1[0] - c.p0[0]), c.p0[1] + t * (c.p1[1] - c.p0[1])];
  }
  var b = figState.curves.b, x = b.xs + t * (b.xe - b.xs);
  return [x, x * x];
}
function curveDeriv(key, t) {
  if (key === 'a') {
    var c = figState.curves.a;
    return [c.p1[0] - c.p0[0], c.p1[1] - c.p0[1]];
  }
  var b = figState.curves.b, dx = b.xe - b.xs, x = b.xs + t * dx;
  return [dx, 2 * x * dx];
}
function fieldAt(p) { return [Math.cos(p[0]), Math.sin(p[0])]; }
function gVal(key, t) {
  var p = curvePoint(key, t), d = curveDeriv(key, t), F = fieldAt(p);
  return F[0] * d[0] + F[1] * d[1];
}
var CUMN = 240;
function cumTable(key) {
  var arr = new Array(CUMN + 1), dt = 1 / CUMN, acc = 0;
  arr[0] = 0;
  for (var i = 1; i <= CUMN; i++) { acc += gVal(key, (i - 0.5) * dt) * dt; arr[i] = acc; }
  return arr;
}
function runningAt(tbl, t) {
  var x = figClamp(t, 0, 1) * CUMN, i = Math.floor(x);
  if (i >= CUMN) return tbl[CUMN];
  return tbl[i] + (tbl[i + 1] - tbl[i]) * (x - i);
}

/* ---------- panels ---------- */
function mkPanel(key, x, y, w, h) {
  var base = (key === 'a')
    ? { xd: [-2.26, 1.22], yd: [-0.82, 2.74], nx: 13, ny: 14 }
    : { xd: [-2.36, 3.60], yd: [-0.48, 4.92], nx: 14, ny: 13 };
  var xr = base.xd[1] - base.xd[0], yr = base.yd[1] - base.yd[0];
  var s = Math.min(w / xr, h / yr);
  var nxr = w / s, nyr = h / s;
  var cx = (base.xd[0] + base.xd[1]) / 2, cy = (base.yd[0] + base.yd[1]) / 2;
  var P = {
    key: key, x: x, y: y, w: w, h: h, s: s, nx: base.nx, ny: base.ny,
    xd: [cx - nxr / 2, cx + nxr / 2],
    yd: [cy - nyr / 2, cy + nyr / 2]
  };
  P.X = function (wx) { return P.x + (wx - P.xd[0]) * P.s; };
  P.Y = function (wy) { return P.y + P.h - (wy - P.yd[0]) * P.s; };
  P.invX = function (px) { return P.xd[0] + (px - P.x) / P.s; };
  P.invY = function (py) { return P.yd[0] + (P.y + P.h - py) / P.s; };
  return P;
}

function figLayout() {
  figPanels = {};
  if (figState.mode === 'both') {
    figPanels.a = mkPanel('a', 24, 62, 240, 250);
    figPanels.b = mkPanel('b', 296, 62, 264, 250);
  } else if (figState.mode === 'a') {
    figPanels.a = mkPanel('a', 30, 64, 300, 310);
  } else {
    figPanels.b = mkPanel('b', 30, 64, 300, 310);
  }
}

/* ---------- static drawing ---------- */
function drawPanelStatic(P) {
  var g = figStatic.group();
  var bg = g.rect(P.w, P.h).move(P.x, P.y).fill(GREENBG);
  bg.css('cursor', 'help');
  bg.on('mousemove', function (e) {
    showTooltip('F = cos(x) i + sin(x) j \u2014 every arrow drawn the same length, so only direction matters. Direction depends on x alone.', e);
  }).on('mouseleave', hideTooltip).on('click', function () {
    showPopup('The field F = cos(x) i + sin(x) j',
      'Both components depend only on x, so the field is identical all the way up each vertical line. Near x = -\u03C0/2 the arrows point straight down, near x = 0 they point straight right, and for x > 0 they tilt up and to the right. Lengths are normalised for readability \u2014 "vectors not to scale".');
  });

  // normalised field lattice
  var dxw = (P.xd[1] - P.xd[0]) / P.nx, dyw = (P.yd[1] - P.yd[0]) / P.ny;
  var L = Math.min(P.w / P.nx, P.h / P.ny) * 0.80;
  var fg = g.group();
  for (var i = 0; i < P.nx; i++) {
    for (var j = 0; j < P.ny; j++) {
      var wx = P.xd[0] + (i + 0.5) * dxw, wy = P.yd[0] + (j + 0.5) * dyw;
      var ux = Math.cos(wx), uy = Math.sin(wx);
      var cx = P.X(wx), cy = P.Y(wy);
      figArrow(fg, cx - ux * L / 2, cy + uy * L / 2, cx + ux * L / 2, cy - uy * L / 2,
        INK, Math.max(0.65, L * 0.075), L * 0.36, 1);
    }
  }

  // axes with arrowheads extending past the frame
  var y0 = P.Y(0), x0 = P.X(0);
  var ag = g.group();
  figArrow(ag, P.x - 14, y0, P.x + P.w + 26, y0, INK, 1.9, 11, 1);
  figArrow(ag, x0, P.y + P.h + 14, x0, P.y - 26, INK, 1.9, 11, 1);
  figLabel(ag, 'x', P.x + P.w + 33, y0 - 14, 16, { italic: true });
  figLabel(ag, 'y', x0 + 14, P.y - 30, 16, { italic: true });

  // ticks
  var tg = g.group(), k, v, fs = (figState.mode === 'both') ? 13 : 15;
  if (P.key === 'a') {
    for (k = 1; k <= 2; k++) {
      tg.line(x0 - 5, P.Y(k), x0 + 5, P.Y(k)).stroke({ color: INK, width: 1.6 });
      figLabel(tg, String(k), x0 - 13, P.Y(k), fs, { anchor: 'end', italic: true });
    }
    var xp = P.X(-Math.PI / 2);
    tg.line(xp, y0 - 5, xp, y0 + 5).stroke({ color: INK, width: 1.6 });
    drawNegPiOver2(tg, xp + 2, y0 + 9, fs);
  } else {
    var xs = [-2, -1, 1, 2, 3];
    for (k = 0; k < xs.length; k++) {
      v = xs[k];
      tg.line(P.X(v), y0 - 5, P.X(v), y0 + 5).stroke({ color: INK, width: 1.6 });
      figLabel(tg, (v < 0 ? '\u2212' : '') + Math.abs(v), P.X(v), y0 + fs + 4, fs, { italic: true });
    }
    for (k = 1; k <= 4; k++) {
      tg.line(x0 - 5, P.Y(k), x0 + 5, P.Y(k)).stroke({ color: INK, width: 1.6 });
      figLabel(tg, String(k), x0 - 12, P.Y(k), fs, { anchor: 'end', italic: true });
    }
  }

  // caption
  figLabel(g, P.key === 'a' ? '(a)' : '(b)', P.x + P.w / 2, P.y + P.h + (figState.mode === 'both' ? 28 : 32),
    figState.mode === 'both' ? 16 : 19, { italic: true });
}

function figBuildStatic() {
  figStatic.clear();
  var keys = Object.keys(figPanels);
  for (var i = 0; i < keys.length; i++) drawPanelStatic(figPanels[keys[i]]);
  var cx = (figState.mode === 'both') ? FIG_W / 2 : (figPanels.a || figPanels.b).x + (figPanels.a || figPanels.b).w / 2;
  figLabel(figStatic, 'Vectors not to scale', cx, 28, 19, { italic: true, fill: '#111' });
}

/* ---------- curve layer ---------- */
function figBuildCurves() {
  figCurveL.clear();
  var keys = Object.keys(figPanels);
  for (var i = 0; i < keys.length; i++) drawCurve(figPanels[keys[i]]);
  figBuildDynamic();
}

function drawCurve(P) {
  var g = figCurveL.group(), key = P.key, i, t, p, d;
  var N = 96, pts = [];
  for (i = 0; i <= N; i++) { t = i / N; p = curvePoint(key, t); pts.push([P.X(p[0]), P.Y(p[1])]); }
  var wid = (figState.mode === 'both') ? 3.6 : 4.4;

  // sign ribbon beneath the curve when decomposition is on
  if (figState.comp) {
    for (i = 0; i < N; i++) {
      var tm = (i + 0.5) / N;
      var dd = curveDeriv(key, tm), dl = Math.hypot(dd[0], dd[1]);
