    ]).fill({ color: RED, opacity: 0.55 });
    tri.css('cursor', 'pointer');
    tri.on('mousemove', function (e) {
      showTooltip('Orientation of C: this is the direction of travel, which fixes the sign of the integral.', e);
    }).on('mouseleave', hideTooltip);
  }

  // endpoints (draggable); start marked with a thin dark ring
  [0, 1].forEach(function (which) {
    var q = curvePoint(key, which);
    var r = (figState.mode === 'both') ? 9 : 11;
    var dot = g.circle(r).center(P.X(q[0]), P.Y(q[1])).fill(RED);
    if (which === 0) dot.stroke({ color: '#7a0b12', width: 1.4 });
    dot.css('cursor', 'grab');
    dot.on('mousedown', function (e) { e.preventDefault(); figDrag = { key: key, which: which }; });
    dot.on('mousemove', function (e) {
      showTooltip((which === 0 ? 'START' : 'END') + ' of C at (' + fmt(q[0]) + ', ' + fmt(q[1]) + ') \u2014 drag to reshape the path', e);
    }).on('mouseleave', hideTooltip);
  });

  // label C
  var lt = (key === 'a') ? 0.60 : 0.88;
  var lp = curvePoint(key, lt);
  var off = (key === 'a') ? [18, 14] : [22, 4];
  figLabel(g, 'C', P.X(lp[0]) + off[0], P.Y(lp[1]) + off[1], (figState.mode === 'both' ? 16 : 19), { italic: true });
}

/* ---------- dynamic layer ---------- */
function figBuildDynamic() {
  figDynL.clear();
  var keys = (figState.mode === 'both') ? ['a', 'b'] : [figState.mode];
  var i;
  for (i = 0; i < keys.length; i++) drawMarker(figPanels[keys[i]]);
  if (!figState.comp) return;
  if (figState.mode === 'both') {
    drawReadoutBoth({ x: 24, y: 356, w: 536, h: 78 }, keys);
    drawInset({ x: 24, y: 444, w: 258, h: 108 }, 'a');
    drawInset({ x: 302, y: 444, w: 258, h: 108 }, 'b');
  } else {
    drawReadoutSingle({ x: 348, y: 70, w: 268, h: 190 }, keys[0]);
    drawInset({ x: 348, y: 280, w: 268, h: 156 }, keys[0]);
  }
}

function drawMarker(P) {
  var key = P.key, t = figState.t;
  var atEnd = (t < 0.015 || t > 0.985);
  if (!figState.comp && atEnd) return;      // keep the default view identical to the textbook figure
  var p = curvePoint(key, t), d = curveDeriv(key, t), F = fieldAt(p);
  var cx = P.X(p[0]), cy = P.Y(p[1]);
  var g = figDynL.group();
  if (!figState.comp) {
    g.circle(11).center(cx, cy).fill('#fff').stroke({ color: RED, width: 2.6 });
    return;
  }
  var dl = Math.hypot(d[0], d[1]);
  if (dl < 1e-9) { g.circle(11).center(cx, cy).fill('#fff').stroke({ color: RED, width: 2.6 }); return; }
  var T = [d[0] / dl, d[1] / dl];
  var dot = F[0] * T[0] + F[1] * T[1];
  var k = Math.min(P.w, P.h) * 0.20;

  var Fx = cx + F[0] * k, Fy = cy - F[1] * k;
  var Tx = cx + T[0] * k, Ty = cy - T[1] * k;
  var Qx = cx + T[0] * dot * k, Qy = cy - T[1] * dot * k;

  // projection band + dashed drop line
  g.line(cx, cy, Qx, Qy).stroke({ color: dot >= 0 ? POS : NEG, width: 9, linecap: 'butt', opacity: 0.45 });
  g.line(Fx, Fy, Qx, Qy).stroke({ color: '#666', width: 1.3, dasharray: '4,3' });

  var av = figArrow(g, cx, cy, Tx, Ty, GRN, 2.6, 10, 1);
  var af = figArrow(g, cx, cy, Fx, Fy, BLUE, 2.6, 10, 1);
  if (af) {
    af.css('cursor', 'pointer');
    af.on('mousemove', function (e) { showTooltip('F = (' + fmt(F[0]) + ', ' + fmt(F[1]) + ') \u2014 the field at this point (unit length)', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () { showPopup('The field vector F', 'F = cos(x) i + sin(x) j has length 1 everywhere here, so only its direction relative to the direction of travel matters.'); });
  }
  if (av) {
    av.css('cursor', 'pointer');
    av.on('mousemove', function (e) { showTooltip('T = (' + fmt(T[0]) + ', ' + fmt(T[1]) + ') \u2014 unit tangent, the direction of travel', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () { showPopup('The unit tangent T', 'T points along C in the chosen orientation. The integrand is F\u00B7T: the signed length of the shaded projection of F onto T \u2014 positive when they agree, negative when they oppose, and exactly zero when F is perpendicular to the path.'); });
  }
  var mk = g.circle(12).center(cx, cy).fill('#fff').stroke({ color: RED, width: 2.6 });
  mk.css('cursor', 'pointer');
  mk.on('mousemove', function (e) { showTooltip('F\u00B7T = ' + fmt(dot) + ' at t = ' + figState.t.toFixed(2), e); })
    .on('mouseleave', hideTooltip);
}

function readoutLines(key) {
  var t = figState.t, p = curvePoint(key, t), d = curveDeriv(key, t), F = fieldAt(p);
  var dl = Math.hypot(d[0], d[1]);
  var T = dl > 1e-9 ? [d[0] / dl, d[1] / dl] : [0, 0];
  var tbl = cumTable(key);
  return {
    p: p, F: F, T: T, dot: F[0] * T[0] + F[1] * T[1],
    run: runningAt(tbl, t), total: tbl[CUMN], t: t
  };
}

function drawReadoutSingle(r, key) {
  var g = figDynL.group();
  var box = g.rect(r.w, r.h).move(r.x, r.y).fill('#ffffff').stroke({ color: '#c9ced4', width: 1 }).radius(6);
  box.css('cursor', 'pointer');
  box.on('click', function () {
    showPopup('Reading the line integral',
      'At each t the point on C carries a field vector F and a unit tangent T. The integrand F\u00B7T is the signed length of F projected onto T; multiplied by arc length and summed it gives \u222B_C F\u00B7dr. It is positive where the path runs with the field, negative where it runs against it, and zero where they are perpendicular.');
  }).on('mousemove', function (e) { showTooltip('Click for how this readout builds the integral', e); })
    .on('mouseleave', hideTooltip);

  var R = readoutLines(key);
  var mono = 'ui-monospace, Consolas, monospace';
  var x = r.x + 13, y = r.y + 20, dy = 21;
  figLabel(g, 'Curve C \u2014 panel (' + key + ')', x, y, 12.5, { anchor: 'start', weight: 'bold', halo: false, family: 'sans-serif' }); y += dy;
  figLabel(g, 't = ' + R.t.toFixed(2), x, y, 11.5, { anchor: 'start', halo: false, family: mono }); y += dy;
  figLabel(g, 'point = (' + fmt(R.p[0]) + ', ' + fmt(R.p[1]) + ')', x, y, 11.5, { anchor: 'start', halo: false, family: mono }); y += dy;
  figLabel(g, 'F = (' + fmt(R.F[0]) + ', ' + fmt(R.F[1]) + ')', x, y, 11.5, { anchor: 'start', halo: false, family: mono, fill: BLUE }); y += dy;
  figLabel(g, 'T = (' + fmt(R.T[0]) + ', ' + fmt(R.T[1]) + ')', x, y, 11.5, { anchor: 'start', halo: false, family: mono, fill: GRN }); y += dy;
  figLabel(g, 'F \u00B7 T = ' + fmt(R.dot), x, y, 11.5, { anchor: 'start', halo: false, family: mono, fill: R.dot >= 0 ? '#1553a8' : '#b4560f' }); y += dy;
  figLabel(g, '\u222B so far = ' + fmt(R.run), x, y, 11.5, { anchor: 'start', halo: false, family: mono }); y += dy;
  figLabel(g, 'total \u222B_C F\u00B7dr = ' + fmt(R.total), x, y, 12, { anchor: 'start', weight: 'bold', halo: false, family: mono, fill: '#8a1020' });
}

function drawReadoutBoth(r, keys) {
  var g = figDynL.group();
  g.rect(r.w, r.h).move(r.x, r.y).fill('#ffffff').stroke({ color: '#c9ced4', width: 1 }).radius(6);
  var mono = 'ui-monospace, Consolas, monospace';
  for (var i = 0; i < keys.length; i++) {
    var key = keys[i], R = readoutLines(key);
    var x = r.x + 16 + i * 272, y = r.y + 19;
    figLabel(g, 'Panel (' + key + ') ' + (key === 'a' ? '\u2014 vertical segment' : '\u2014 parabolic arc'),
      x, y, 11.5, { anchor: 'start', weight: 'bold', halo: false, family: 'sans-serif' });
    y += 20;
    figLabel(g, 'F\u00B7T = ' + fmt(R.dot) + '   \u222B so far = ' + fmt(R.run), x, y, 11, { anchor: 'start', halo: false, family: mono });
    y += 20;
    figLabel(g, 'total \u222B_C F\u00B7dr = ' + fmt(R.total), x, y, 11.5, { anchor: 'start', weight: 'bold', halo: false, family: mono, fill: '#8a1020' });
  }
}

function drawInset(r, key) {
  var g = figDynL.group();
  g.rect(r.w, r.h).move(r.x, r.y).fill('#ffffff').stroke({ color: '#c9ced4', width: 1 }).radius(6);
  figLabel(g, 'F\u00B7T ds/dt  vs  t   (signed area = \u222B)', r.x + r.w / 2, r.y + 13, 10, { halo: false, family: 'sans-serif', fill: '#333' });

  var px = r.x + 24, py = r.y + 26, pw = r.w - 38, ph = r.h - 44;
  var N = 72, i, vals = [], mx = 1e-6;
  for (i = 0; i <= N; i++) { var v = gVal(key, i / N); vals.push(v); mx = Math.max(mx, Math.abs(v)); }
  mx *= 1.15;
  var mapT = function (t) { return px + t * pw; };
  var mapG = function (v) { return py + ph / 2 - (v / mx) * (ph / 2); };

  var tc = figState.t;
  for (i = 0; i < N; i++) {
    var t0 = i / N, t1 = (i + 1) / N;
    if (t0 >= tc) break;
    var te = Math.min(t1, tc);
    var v0 = vals[i], v1 = v0 + (vals[i + 1] - v0) * ((te - t0) / (t1 - t0));
    var mid = (v0 + v1) / 2;
    g.polygon([[mapT(t0), mapG(0)], [mapT(t0), mapG(v0)], [mapT(te), mapG(v1)], [mapT(te), mapG(0)]])
      .fill({ color: mid >= 0 ? POS : NEG, opacity: 0.55 }).stroke('none');
  }
  g.line(px, mapG(0), px + pw, mapG(0)).stroke({ color: '#888', width: 1, dasharray: '3,3' });
  figLabel(g, '0', px - 9, mapG(0), 9.5, { halo: false, family: 'sans-serif', fill: '#666' });

  var pts = [];
  for (i = 0; i <= N; i++) pts.push([mapT(i / N), mapG(vals[i])]);
  g.polyline(pts).fill('none').stroke({ color: '#222', width: 1.6, linejoin: 'round' });
  g.line(mapT(tc), py, mapT(tc), py + ph).stroke({ color: RED, width: 1.3 });
  g.circle(6).center(mapT(tc), mapG(gVal(key, tc))).fill(RED);
  figLabel(g, 't = 0', px, py + ph + 9, 9.5, { halo: false, family: 'sans-serif', fill: '#666' });
  figLabel(g, 't = 1', px + pw, py + ph + 9, 9.5, { halo: false, family: 'sans-serif', fill: '#666' });

  var hit = g.rect(r.w, r.h).move(r.x, r.y).fill('#fff').opacity(0);
  hit.css('cursor', 'pointer');
  hit.on('mousemove', function (e) { showTooltip('Signed area under F\u00B7T ds/dt from 0 to t equals the running line integral', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('The accumulation picture',
        'Blue area is added (the path moves with the field) and orange area is subtracted (it moves against the field). Where F is perpendicular to the path the curve crosses zero and nothing is accumulated. The whole signed area from t = 0 to t = 1 is \u222B_C F\u00B7dr.');
    });
}

/* ---------- rebuild ---------- */
function figRebuildAll() {
  figLayout();
  figBuildStatic();
  figBuildCurves();
}

/* ---------- dragging ---------- */
var figDrag = null;
function figClientToUser(e) {
  var pt = figDraw.node.createSVGPoint();
  pt.x = e.clientX; pt.y = e.clientY;
  return pt.matrixTransform(figDraw.node.getScreenCTM().inverse());
}
document.addEventListener('mousemove', function (e) {
  if (!figDrag) return;
  var P = figPanels[figDrag.key];
  if (!P) return;
  var u = figClientToUser(e);
  var wx = P.invX(u.x), wy = P.invY(u.y);
  if (figDrag.key === 'a') {
    wx = figClamp(wx, P.xd[0] + 0.25, P.xd[1] - 0.25);
    wy = figClamp(wy, P.yd[0] + 0.25, P.yd[1] - 0.25);
    var c = figState.curves.a;
    var other = (figDrag.which === 0) ? c.p1 : c.p0;
    if (Math.hypot(wx - other[0], wy - other[1]) < 0.25) return;
    if (figDrag.which === 0) c.p0 = [wx, wy]; else c.p1 = [wx, wy];
  } else {
    wx = figClamp(wx, -2.15, 2.15);
    var b = figState.curves.b;
    var o = (figDrag.which === 0) ? b.xe : b.xs;
    if (Math.abs(wx - o) < 0.25) return;
    if (figDrag.which === 0) b.xs = wx; else b.xe = wx;
  }
  figBuildCurves();
});
document.addEventListener('mouseup', function () { figDrag = null; });

/* ---------- controls ---------- */
function toggle_panelView(v) {
  figState.mode = v;
  figRebuildAll();
}
function update_paramT(v) {
  figState.t = v;
  figBuildDynamic();
}
function toggle_showComponents(on) {
  figState.comp = on;
  figBuildCurves();
}
var figSweeping = false;
function trigger_sweep() {
  if (figSweeping) { figSweeping = false; return; }
  if (!figState.comp) {
    figState.comp = true;
    document.getElementById('showComponentsInput').checked = true;
    figBuildCurves();
  }
  figSweeping = true;
  var t0 = performance.now(), dur = 5200;
  function frame(now) {
    if (!figSweeping) return;
    var p = Math.min(1, (now - t0) / dur);
    setTFromCode(p);
    if (p < 1) requestAnimationFrame(frame); else figSweeping = false;
  }
  setTFromCode(0);
  requestAnimationFrame(frame);
}
function setTFromCode(v) {
  figState.t = v;
  var inp = document.getElementById('paramTInput');
  var out = document.getElementById('paramTVal');
  if (inp) inp.value = v;
  if (out) out.value = v.toFixed(2);
  figBuildDynamic();
}

/* ---------- demo steps ---------- */
var figSteps = [
  {
    title: '1. The field alone',
    narr: 'The green panel shows F = cos(x) i + sin(x) j, drawn with all arrows the same length so only direction is meaningful. The direction depends only on x: vertical columns of identical arrows, swinging from straight down near x = -\u03C0/2 to straight right near x = 0.',
    st: { mode: 'a', t: 0, comp: false }
  },
  {
    title: '2. Curve (a): travelling downward at x = -\u03C0/2',
    narr: 'C starts at the ringed dot (-\u03C0/2, 2) and is traversed DOWN to (-\u03C0/2, 1) \u2014 the arrowhead shows the orientation. Along this column the field also points straight down, exactly with the travel direction, so F\u00B7T = +1 everywhere.',
    st: { mode: 'a', t: 0, comp: true }
  },
  {
    title: '3. Step along (a)',
    narr: 'Slide t: neither the field vector nor the tangent ever changes, so F\u00B7T stays constant at +1 and the running integral grows linearly to 1 = the length of C. The whole curve is shaded blue: every piece adds.',
    st: { mode: 'a', t: 1, comp: true }
  },
  {
    title: '4. Curve (b): the parabola y = x\u00B2',
    narr: 'Now the path runs from (-1, 1) down through the origin and up to (2, 4). The tangent swings from down-right to steeply up-right while the field rotates with x, so F\u00B7T changes sign \u2014 the orange stretch near the start subtracts, the blue stretch adds.',
    st: { mode: 'b', t: 0, comp: true }
  },
  {
    title: '5. Accumulate along (b)',
    narr: 'Press "Traverse C and accumulate": the running total dips where F opposes the tangent, pauses where F is perpendicular to the path (F\u00B7T = 0), and climbs where they align. The inset shows the signed area that is the integral.',
    st: { mode: 'b', t: 1, comp: true }
  },
  {
    title: '6. Compare the two paths',
    narr: 'Side by side, the short vertical segment and the long curved arc give very different values in the same field. Drag the endpoint dots of either curve and watch the number move \u2014 the integral measures alignment with F along the oriented path.',
    st: { mode: 'both', t: 0.5, comp: true }
  }
];
var figStep = 0;
function applyStep(i) {
  figSweeping = false;
  figStep = ((i % figSteps.length) + figSteps.length) % figSteps.length;
  var s = figSteps[figStep];
  figState.mode = s.st.mode;
  figState.t = s.st.t;
  figState.comp = s.st.comp;
  document.getElementById('panelViewInput').value = s.st.mode;
  document.getElementById('paramTInput').value = s.st.t;
  document.getElementById('paramTVal').value = s.st.t.toFixed(2);
  document.getElementById('showComponentsInput').checked = s.st.comp;
  document.getElementById('demoTitle').textContent = s.title;
  document.getElementById('demoNarration').textContent = s.narr;
  document.getElementById('stepLabel').textContent = (figStep + 1) + ' / ' + figSteps.length;
  figRebuildAll();
}
function nextStep() { applyStep(figStep + 1); }
function prevStep() { applyStep(figStep - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: The line integral ∫_C F·dr accumulates the component of the vector field F = cos(x) i + sin(x) j that lies along the direction of travel, so its value depends on how the oriented curve is aligned with the field, not merely on its endpoints or length.
KEY INSIGHT (what students should walk away understanding): A line integral measures alignment: at every point only the component of F along the direction you are moving counts, so a path that runs with the field accumulates positively, a path that runs against it subtracts, and a path perpendicular to it contributes nothing at all.
DEMO STEPS: 6 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "The line integral ∫_C F·dr accumulates the component of the vector field F = cos(x) i + sin(x) j that lies along the direction of travel, so its value depends on how the oriented curve is aligned with the field, not merely on its endpoints or length.",
  "figureType": "diagram",
  "elements": [
    "Two stacked panels labeled (a) and (b), each a pale green shaded rectangle containing a vector field plot",
    "Italic title above panel (a): 'Vectors not to scale'",
    "Panel (a): x-axis with arrowhead and label x, y-axis with arrowhead and label y",
    "Panel (a): tick labels 1 and 2 on the y-axis, tick label -π/2 on the x-axis (stacked fraction form)",
    "Panel (a): grid of small black arrows representing F = cos(x) i + sin(x) j, all drawn at equal length (normalized), rotating direction with x",
    "Panel (a): red vertical segment C at x = -π/2 from (-π/2, 2) down to (-π/2, 1), with red filled dot endpoints and a translucent red arrowhead midway pointing downward, label C beside it",
    "Panel (b): x-axis with tick labels -2, -1, 1, 2, 3 and y-axis with tick labels 1, 2, 3, 4",
    "Panel (b): same normalized arrow field on the green background, spanning roughly x ∈ [-2.3, 3.2], y ∈ [-0.6, 4.6]",
    "Panel (b): red parabolic arc y = x² from (-1, 1) to (2, 4), with red filled dot endpoints and two translucent red arrowheads showing orientation (down-left branch then up-right branch), label C near the upper end",
    "Panel captions '(a)' and '(b)' below each frame",
    "Readout panel (added for the demo): current parameter t, position (x, y), field vector F at the point, unit tangent T, dot product F·T, and running value of ∫_C F·dr",
    "Moving marker: a hollow red point on C with a blue field-vector arrow and a green tangent-vector arrow drawn from it, plus a shaded projection showing the component of F along T",
    "Small inset accumulation plot of F·T ds versus t whose signed area equals the line integral"
  ],
  "interactions": [
    {
      "id": "panelView",
      "type": "toggle",
      "teaches": "That the same field gives very different integrals along different oriented curves: the short vertical segment rides almost perpendicular/antiparallel to the field, while the long parabola sweeps through many field orientations.",
      "label": "Curve C",
      "options": [
        "(a) vertical segment",
        "(b) parabolic arc",
        "both side by side"
      ],
      "default": "(a) vertical segment"
    },
    {
      "id": "dragEndpoints",
      "type": "drag",
      "teaches": "That reshaping the path — moving its endpoints through the field — continuously changes the accumulated integral, revealing which stretches of the curve contribute positively and which negatively.",
      "teachesNote": "Drag the red endpoint dots; the curve (segment or parabola through the endpoints) and the live integral update together."
    },
    {
      "id": "paramT",
      "type": "slider",
      "teaches": "That the integral is built pointwise: at each t the learner sees F, the unit tangent T, and their dot product, and watches the running total grow or shrink accordingly.",
      "label": "Parameter t along C",
      "range": [
        0,
        1,
        0.01
      ],
      "default": 0
    },
    {
      "id": "sweep",
      "type": "animation",
      "teaches": "That the line integral is a continuous accumulation of F·T ds as the point traverses C in its given orientation.",
      "label": "Traverse C and accumulate",
      "loop": false
    },
    {
      "id": "showComponents",
      "type": "toggle",
      "teaches": "That only the projection of F onto the tangent direction matters — the perpendicular part of F contributes nothing to the line integral.",
      "label": "Show F·T decomposition",
      "default": true
    }
  ],
  "demo_steps": [
    {
      "title": "The field alone",
      "narration": "The green panel shows F = cos(x) i + sin(x) j, drawn with all arrows the same length so only direction is meaningful. Notice the direction depends only on x: vertical columns of identical arrows, swinging from downward near x = -π/2 to rightward near x = 0.",
      "state": {
        "panelView": "(a) vertical segment",
        "paramT": 0,
        "showComponents": false
      }
    },
    {
      "title": "Curve (a): straight down at x = -π/2",
      "narration": "The oriented curve C runs from (-π/2, 2) down to (-π/2, 1). Along this whole column the field points straight down — exactly with the direction of travel — so every contribution is positive.",
      "state": {
        "panelView": "(a) vertical segment",
        "paramT": 0,
        "showComponents": true
      }
    },
    {
      "title": "Step along (a)",
      "narration": "Slide t: the field vector never changes, the tangent never changes, so F·T is constant and the running integral grows linearly to its final value.",
      "state": {
        "panelView": "(a) vertical segment",
        "paramT": 1,
        "showComponents": true
      }
    },
    {
      "title": "Curve (b): the parabola y = x²",
      "narration": "Now the path runs from (-1, 1) down through the origin and up to (2, 4). The tangent swings from pointing down-right to steeply up-right while the field rotates with x, so F·T changes sign along the way.",
      "state": {
        "panelView": "(b) parabolic arc",
        "paramT": 0,
        "showComponents": true
      }
    },
    {
      "title": "Accumulate along (b)",
      "narration": "Play the sweep: watch the running total dip where F opposes the tangent and climb where they align. The inset shows the signed area that is the integral.",
      "state": {
        "panelView": "(b) parabolic arc",
        "paramT": 1,
        "showComponents": true
      }
    },
    {
      "title": "Compare the two paths",
      "narration": "Side by side, the short vertical segment and the long curved arc give different values in the same field. Then drag the endpoints of either curve and watch the number move — the integral is a property of the oriented path, not just its endpoints.",
      "state": {
        "panelView": "both side by side",
        "paramT": 0.5,
        "showComponents": true
      }
