    narr: 'Side by side: the short upward segment runs against the field and gives -1, while the long arc runs mostly with it and gives a large positive value. Drag the endpoint dots of either curve and watch the number move \u2014 the integral measures alignment with F along the oriented path.',
    st: { mode: 'both', t: 0.5, comp: true }
  }
];
var figStep = 0;
function applyStep(i) {
  figSweeping = false;
  figStep = ((i % figSteps.length) + figSteps.length) % figSteps.length;
  var s = figSteps[figStep];
  figState.mode = s.st.mode;
  figState.t = s.st.t;
  figState.comp = s.st.comp;
  document.getElementById('panelViewInput').value = s.st.mode;
  document.getElementById('paramTInput').value = s.st.t;
  document.getElementById('paramTVal').value = s.st.t.toFixed(2);
  document.getElementById('showComponentsInput').checked = s.st.comp;
  document.getElementById('demoTitle').textContent = s.title;
  document.getElementById('demoNarration').textContent = s.narr;
  document.getElementById('stepLabel').textContent = (figStep + 1) + ' / ' + figSteps.length;
  figRebuildAll();
}
function nextStep() { applyStep(figStep + 1); }
function prevStep() { applyStep(figStep - 1); }

applyStep(0);
